// First-start demo houses (spec/architecture/persistence.md#demo-houses): an installation whose data directory has
// never held a house starts with the demo houses generated by `npm run demo:build` (server/demo-houses/*.json).
// Each becomes a new house with a fresh Git history of one commit. config/demo-seeded records that seeding is
// done, so it happens at most once: a deleted demo house never comes back, and an installation that already has
// houses is never seeded. Failures are logged and never stop the server.
import { readFile, readdir } from "node:fs/promises";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import type { HouseDocument } from "../../shared/domain/schemas/house";
import { isRecord, parseJson } from "../lib/json";
import { atomicWriteFile } from "../repositories/atomic";
import { listChildDirectories, readTextIfExists } from "../repositories/files";
import { decodeHouseText } from "../repositories/houseRepository";
import type { ServiceContext } from "./context";
import { createHouseFromDocument } from "./houseService";

export const defaultDemoHousesDir = resolve(fileURLToPath(new URL(".", import.meta.url)), "../demo-houses");

/** A demo house file as a current, valid document, or the reason it is not one. */
const readDemoDocument = async (file: string): Promise<HouseDocument | string> => {
  const text = await readFile(file, "utf8");
  const parsed = parseJson(text);
  const fileId =
    parsed.ok && isRecord(parsed.value) && typeof parsed.value.id === "string" ? parsed.value.id : "";
  const decoded = decodeHouseText(text, fileId);
  if (decoded.kind === "invalid") return decoded.message;
  if (decoded.problems.length > 0) return decoded.problems.map((problem) => problem.message).join("; ");
  return decoded.document;
};

const seed = async (context: ServiceContext, directory: string): Promise<void> => {
  const { paths, log } = context;
  if ((await readTextIfExists(paths.demoSeededMarker)) !== undefined) return;
  const existing = [
    ...(await listChildDirectories(paths.dataDir)),
    ...(await listChildDirectories(paths.trashDir)),
  ];
  const marker = (seeded: readonly string[]): Promise<void> =>
    atomicWriteFile(
      paths.demoSeededMarker,
      `${JSON.stringify({ schemaVersion: 1, seededAt: new Date().toISOString(), houses: seeded }, null, 2)}\n`,
    );
  if (existing.length > 0) {
    // An installation that already holds houses (or trashed ones) is never seeded later.
    await marker([]);
    return;
  }
  const files = (await readdir(directory)).filter((name) => name.endsWith(".json")).sort();
  const seeded: string[] = [];
  for (const name of files) {
    try {
      const document = await readDemoDocument(join(directory, name));
      if (typeof document === "string") {
        log.warn({ file: name, problem: document }, "Skipped an invalid demo house");
        continue;
      }
      const card = await createHouseFromDocument(context, document, "Create demo house");
      seeded.push(card.id);
      log.info({ houseId: card.id, name: card.name }, "Created a demo house");
    } catch (error: unknown) {
      log.warn({ file: name, err: error }, "Could not create a demo house");
    }
  }
  if (seeded.length > 0) await marker(seeded);
};

/**
 * Seeds the demo houses into a data directory that has never held a house (no marker, data/ and trash/ empty).
 * Run on startup after prepareStorage; `enabled` false (HOMEPLAN_SEED_DEMOS=0) skips it and writes no marker.
 */
export const seedDemoHouses = async (
  context: ServiceContext,
  enabled: boolean,
  directory: string = defaultDemoHousesDir,
): Promise<void> => {
  if (!enabled) return;
  try {
    await seed(context, directory);
  } catch (error: unknown) {
    context.log.warn({ err: error }, "Demo house seeding failed");
  }
};
